base.apps/service/src/features/booking/pricin:
/** Стоимость записи в копейках: скидка в процентах от базовой цены. */
export function applyDiscount(priceCents: number, percent: number): number {
  const discount = Math.round((priceCents * percent) / 100);
  return priceCents - discount;
}

import assert from 'node:assert/strict';
import { describe, test } from 'node:test';

import { applyDiscount } from './pricing.js';

describe('applyDiscount', () => {
  test('скидка округляется в пользу клиента', () => {
    assert.equal(applyDiscount(101, 50), 50);
  });
});

